SELECT DISTINCT ?motherInLaw ?motherInLawLabel ?spouse WHERE {
  { ?spouse dbp:spouse dbr:Baketwernel } UNION { dbr:Baketwernel dbp:spouse ?spouse } UNION { ?spouse dbo:spouse dbr:Baketwernel } UNION { dbr:Baketwernel dbo:spouse ?spouse } .
  OPTIONAL { ?spouse dbp:mother ?motherInLaw . }
  OPTIONAL { ?spouse dbo:mother ?motherInLaw . }
  OPTIONAL { ?motherInLaw rdfs:label ?motherInLawLabel . FILTER(lang(?motherInLawLabel) = "en") }
}

SELECT DISTINCT ?mother ?motherLabel ?spouse ?spouseLabel WHERE {
  { ?spouse dbp:spouse dbr:Baketwernel } UNION { dbr:Baketwernel dbp:spouse ?spouse } UNION { ?spouse dbo:spouse dbr:Baketwernel } UNION { dbr:Baketwernel dbo:spouse ?spouse } .
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(lang(?spouseLabel) = "en") }

  # option 1: direct mother link
  OPTIONAL { ?spouse dbp:mother ?mother . }
  OPTIONAL { ?spouse dbo:mother ?mother . }

  # option 2: find a Takhat resource whose abstract mentions the spouse label
  OPTIONAL {
    ?motherCandidate rdfs:label ?mcLabel . FILTER(lang(?mcLabel) = "en") . FILTER(contains(lcase(str(?mcLabel)), "takhat")) .
    ?motherCandidate dbo:abstract ?mcAbs . FILTER(lang(?mcAbs) = "en") .
    FILTER(bound(?spouseLabel) && contains(lcase(str(?mcAbs)), lcase(str(?spouseLabel))))
  }

  BIND(COALESCE(?mother, ?motherCandidate) AS ?mother)
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
  FILTER(bound(?mother))
}

